@Component
public class RandomNumberAllocator {
    private final JdbcTemplate jdbc;
    @Transactional(propagation = Propagation.REQUIRES_NEW)
    public long allocate(long trialId, long centerId) {
        int updated = jdbc.update("UPDATE random_counter SET next_no = next_no + 1 WHERE trial_id=? AND center_id=?", trialId, centerId);
        if (updated == 0) {
            jdbc.update("INSERT INTO random_counter (trial_id, center_id, next_no) VALUES (?,?,2)", trialId, centerId);
            return 1;
        }
        Long next = jdbc.queryForObject("SELECT next_no FROM random_counter WHERE trial_id=? AND center_id=?", Long.class, trialId, centerId);
        return next - 1;
    }
}
```

