private char blockArm(long trialId, long centerId, long randomNo) {
    long blockNo = (randomNo - 1) / 4;
    int pos = (int) ((randomNo - 1) % 4);
    String arm = repo.findBlockArm(trialId, centerId, blockNo, pos);
    if (arm == null) {
        generateBlock(trialId, centerId, blockNo);
        arm = repo.findBlockArm(...);
    }
    return arm.charAt(0);
}

private void generateBlock(trialId, centerId, blockNo) {
    // previous block last two arms
    List<String> prev = repo.blockArms(trialId, centerId, blockNo - 1); // empty if blockNo==0
    List<Character> arms = new ArrayList<>(List.of('T','T','C','C'));
    for (int attempt = 0; attempt < 16; attempt++) {
        Collections.shuffle(arms, secureRandom);
        if (prev.size() == 4 && prev.get(2) == prev.get(3) && arms.get(0) == prev.get(3).charAt(0) && arms.get(1) == prev.get(3).charAt(0)) continue;
        break;
    }
    // insert 4 rows; on duplicate (concurrent), ignore and re-read
    try { insert rows } catch (DuplicateKeyException e) { /* re-read */ }
}
